import java.util.*;

class Solution {
    public int calculate(String s) {
        Deque<Integer> st = new ArrayDeque<>();
        char op = '+';
        int num = 0, n = s.length();
        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            if (Character.isDigit(ch)) num = num * 10 + (ch - '0');
            if ((!Character.isDigit(ch) && ch != ' ') || i == n - 1) {
                if (op == '+') st.push(num);
                else if (op == '-') st.push(-num);
                else if (op == '*') st.push(st.pop() * num);   // apply * immediately
                else st.push(st.pop() / num);                  // truncates toward zero
                op = ch;
                num = 0;
            }
        }
        int sum = 0;
        for (int t : st) sum += t;
        return sum;
    }
}

