class Solution:
    def calculate(self, s: str) -> int:
        st = []; num = 0; op = "+"
        for i, c in enumerate(s + "+"):
            if c.isdigit(): num = num * 10 + int(c)
            elif c in "+-*/":
                if op == "+": st.append(num)
                elif op == "-": st.append(-num)
                elif op == "*": st.append(st.pop() * num)
                else: st.append(int(st.pop() / num))
                op, num = c, 0
        return sum(st)

