function calculate(s) {
  const toks = s.replace(/\s+/g, "").match(/\d+|[-+*/]/g);
  let i = 0;
  const term = () => { let v = Number(toks[i++]); while (i < toks.length && (toks[i] === "*" || toks[i] === "/")) { const op = toks[i++], b = Number(toks[i++]); v = op === "*" ? v * b : Math.trunc(v / b); } return v; };
  let res = term();
  while (i < toks.length) { const op = toks[i++]; const t = term(); res = op === "+" ? res + t : res - t; }
  return res;
}
